'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict');
const fs=require('node:fs'),path=require('node:path');
const root=path.resolve(__dirname,'../../..');
const read=p=>fs.readFileSync(path.join(root,p),'utf8').replace(/\r\n?/g,'\n');
const sources=['packages/cloud-sync/core.js','packages/cloud-sync/hash.js',
 'packages/cloud-sync/providers.js'];
const header='// Generated by scripts/release/bundle_cloud_modules.py; do not edit directly.\n'+
 '// Restricted desktop runtime: no OAuth tokens, no automatic syncing.\n';
test('embedded desktop cloud modules exactly match maintained shared source modules',()=>{
 const expected=header+sources.map(p=>'// SOURCE: '+p+'\n'+read(p).trim()+'\n').join('\n');
 assert.equal(read('apps/desktop-shared/src/cloud_modules.js'),expected);
});
test('cloud reader and library are injected before the desktop panel under the same CSP nonce',()=>{
 const main=read('apps/desktop-shared/src/main.go');
 const a=main.indexOf('"+string(cloudModules)+"'),b=main.indexOf('"+string(cloudReader)+"'),
  c=main.indexOf('"+string(cloudLibrary)+"'),d=main.indexOf('"+string(cloudSyncUI)+"'),
  e=main.indexOf('"+string(cloudPanel)+"');
 assert.ok(a>0&&b>a&&c>b&&d>c&&e>d);
 for(const name of ['cloud_modules.js','cloud_reader.js','cloud_library_ui.js','cloud_sync_ui.js'])
  assert.ok(main.includes(name),'Missing embedded '+name);
 assert.match(main,/cspNonce/);
 const panel=read('apps/desktop-shared/src/cloud_panel.js');
 assert.match(panel,/GlaukaCloudLibrary\?\.open/);
 assert.match(panel,/GlaukaCloudLibrary\?\.reset/);
 const library=read('apps/desktop-shared/src/cloud_library_ui.js');
 assert.match(library,/isAllowed:/);
 assert.match(library,/epoch\+\+/);
 assert.match(library,/busy/);
});
test('Cloud UI is opt-in, never treats connected as synced and leaves the manual recovery flow intact',()=>{
 const panel=read('apps/desktop-shared/src/cloud_panel.js'),
  library=read('apps/desktop-shared/src/cloud_library_ui.js');
 assert.match(panel,/Sync non attiva/);
 assert.match(panel,/Sincronizzazione automatica/);
 assert.match(panel,/GlaukaCloudSync\.setEnabled/);
 assert.match(read('apps/desktop-shared/src/cloud_sync_ui.js'),/enabled=provider/);
 assert.doesNotMatch(library,/flushAll\(|\.flush\(|\.save\(/);
 assert.match(library,/Recupera copia/);
 assert.match(library,/Conferma/);
 assert.match(library,/Esporta subito un backup/);
});
